import { env } from '../config/env.js';
import { ApiError } from '../utils/ApiError.js';
import { logger } from '../utils/logger.js';
import { guardReply, preflight } from './guard.js';
import { knowledgeFor } from './knowledge.js';
import { buildSystemMessage } from './prompt.js';

/**
 * The AI assistant. Stateless: each request carries the conversation so far, the answer is generated by a model running in Ollama
 * (POST /api/chat) using only the website's public content, and nothing (messages or answers) is stored or logged. Only this server talks
 * to Ollama; the browser never does. Ollama's address, model and optional proxy key come from the server environment and are never sent
 * to the browser or returned in any response.
 */
const UNAVAILABLE = 'The AI assistant is not available right now. Please use the Contact page to reach our team.';
const BUSY = 'The AI assistant is busy right now. Please try again in a moment, or use the Contact page to reach our team.';
const TIMED_OUT = 'The AI assistant took too long to answer. Please try again.';

let pending = 0;

const unavailable = () => new ApiError(503, UNAVAILABLE, [], 'CHATBOT_UNAVAILABLE');

function headers() {
  return { 'Content-Type': 'application/json', Accept: 'application/json', ...(env.OLLAMA_API_KEY ? { Authorization: `Bearer ${env.OLLAMA_API_KEY}` } : {}) };
}

/** One call to Ollama with a hard timeout. Throws the raw failure; callers turn it into a safe, fixed message. */
async function callOllama(path, { method = 'GET', body, timeoutMs }) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${env.OLLAMA_BASE_URL}${path}`, { method, headers: headers(), body: body ? JSON.stringify(body) : undefined, signal: controller.signal, redirect: 'error' });
    const text = await response.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch { /* handled by the caller */ }
    return { ok: response.ok, status: response.status, json };
  } finally {
    clearTimeout(timer);
  }
}

const modelMatches = (installed, wanted) => installed === wanted || installed === `${wanted}:latest` || (!wanted.includes(':') && installed.startsWith(`${wanted}:`));

let statusCache = { at: 0, value: null };
export const clearAvailabilityCache = () => { statusCache = { at: 0, value: null }; };

/**
 * Is the assistant able to answer right now: is Ollama reachable and is the configured model installed? Asked of Ollama itself (not
 * assumed) and remembered for a few seconds. `reason` is for the server log and the setup check only; visitors only ever see a boolean.
 */
export async function checkAvailability({ fresh = false } = {}) {
  if (!fresh && statusCache.value && Date.now() - statusCache.at < 10_000) return statusCache.value;
  let value;
  try {
    const { ok, json } = await callOllama('/api/tags', { timeoutMs: 4000 });
    if (!ok || !Array.isArray(json?.models)) value = { available: false, reason: 'ollama_error' };
    else if (!json.models.some((model) => modelMatches(model.name ?? model.model ?? '', env.OLLAMA_MODEL))) value = { available: false, reason: 'model_missing' };
    else value = { available: true, reason: null };
  } catch {
    value = { available: false, reason: 'ollama_unreachable' };
  }
  statusCache = { at: Date.now(), value };
  return value;
}

/** What went wrong, for the operator's log. Never contains visitor text, and only a fixed phrase from Ollama's reply. */
function describeFailure(error, response) {
  if (response) return response.status === 404 ? `model "${env.OLLAMA_MODEL}" is not installed (run: ollama pull ${env.OLLAMA_MODEL})` : `Ollama answered HTTP ${response.status}`;
  const code = error?.cause?.code ?? error?.code;
  return code ? `could not reach Ollama (${code})` : `request to Ollama failed (${error?.name ?? 'Error'})`;
}

const HISTORY_CHAR_BUDGET = 2400;

/** The newest turns that fit the budget (the visitor's latest message always stays), still starting with a visitor message. */
export function fitHistory(messages) {
  const kept = [];
  let used = 0;
  for (const message of [...messages].reverse()) {
    if (kept.length > 0 && used + message.content.length > HISTORY_CHAR_BUDGET) break;
    kept.unshift(message);
    used += message.content.length;
  }
  while (kept.length > 1 && kept[0].role !== 'user') kept.shift();
  return kept;
}

const recentVisitorText = (messages) => messages.filter((item) => item.role === 'user').slice(-2).map((item) => item.content).join(' ');
const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Website pages the answer mentions, as buttons for the widget. Only paths that really exist on the site are ever returned. */
export function linksIn(reply, routes) {
  const found = [];
  for (const route of routes) {
    if (route.path === '/') continue;
    const match = new RegExp(`(^|[^\\w/-])${escapeRegex(route.path)}(?![\\w/-])`).exec(reply);
    if (match && !found.some((item) => item.path === route.path)) found.push({ label: route.label, path: route.path, at: match.index });
  }
  // In the order the answer mentions them.
  return found.sort((a, b) => a.at - b.at).slice(0, 3).map(({ label, path }) => ({ label, path }));
}

/** Plain text only: the widget renders it as text, so stray markdown is removed rather than shown as symbols. */
export function tidy(text) {
  return String(text ?? '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/\*\*(.+?)\*\*/gs, '$1')
    .replace(/__(.+?)__/gs, '$1')
    .replace(/`+/g, '')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^[ \t]*[*•][ \t]+/gm, '- ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

export async function reply(messages) {
  // A shipment look-up or an attempt to extract the instructions gets a fixed answer and never reaches the model.
  const fixed = preflight(messages.at(-1).content);
  if (fixed) return { reply: fixed, links: linksIn(fixed, (await knowledgeFor('', 1)).knowledge.routes) };
  if (pending >= env.CHATBOT_MAX_PENDING) throw new ApiError(503, BUSY, [], 'CHATBOT_BUSY');
  pending += 1;
  try {
    const { knowledge, chunks } = await knowledgeFor(recentVisitorText(messages), env.CHATBOT_CONTEXT_CHUNKS);
    const startedAt = Date.now();
    let response;
    try {
      response = await callOllama('/api/chat', {
        method: 'POST',
        timeoutMs: env.OLLAMA_TIMEOUT_MS,
        body: {
          model: env.OLLAMA_MODEL,
          stream: false,
          keep_alive: /^\d+$/.test(env.OLLAMA_KEEP_ALIVE) ? Number(env.OLLAMA_KEEP_ALIVE) : env.OLLAMA_KEEP_ALIVE,
          options: { temperature: env.OLLAMA_TEMPERATURE, num_ctx: env.OLLAMA_NUM_CTX, num_predict: env.OLLAMA_MAX_TOKENS },
          messages: [
            { role: 'system', content: buildSystemMessage({ routes: knowledge.routes, chunks, company: knowledge.company }) },
            ...fitHistory(messages).map(({ role, content }) => ({ role, content })),
          ],
        },
      });
    } catch (error) {
      if (error?.name === 'AbortError') {
        logger.warn(`Chatbot: Ollama did not answer within ${env.OLLAMA_TIMEOUT_MS} ms.`);
        throw new ApiError(504, TIMED_OUT, [], 'CHATBOT_TIMEOUT');
      }
      logger.error(`Chatbot: ${describeFailure(error)}.`);
      clearAvailabilityCache();
      throw unavailable();
    }

    const content = response.json?.message?.content;
    if (!response.ok || typeof content !== 'string') {
      logger.error(`Chatbot: ${describeFailure(null, response)}${response.ok ? ' (unexpected response shape)' : ''}.`);
      clearAvailabilityCache();
      throw unavailable();
    }
    const text = guardReply(tidy(content));
    if (!text) {
      logger.warn('Chatbot: the model returned no text.');
      throw unavailable();
    }
    // Timing and counts only. Never the visitor's words or the answer.
    logger.info(`Chatbot: answered in ${Date.now() - startedAt} ms (${response.json.prompt_eval_count ?? '?'} prompt tokens, ${response.json.eval_count ?? '?'} generated).`);
    return { reply: text, links: linksIn(text, knowledge.routes) };
  } finally {
    pending -= 1;
  }
}
